        if (ImGui::Button(" < ", ImVec2(bw, 0))) nextScene(-1);
        ImGui::SameLine();
        ImGui::SetNextItemWidth(ImGui::GetContentRegionAvail().x - bw - ImGui::GetStyle().ItemSpacing.x);
